import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';
import { closeDatabase, query, ready } from '../lib/pay/db';
import { loadCredentials } from '../lib/pay/credentials';

async function main() {
  // Validate the only CyberSource credential source before changing any setup data.
  await loadCredentials();
  const envPath = path.resolve('.env.local');
  let contents = await fs.readFile(envPath, 'utf8');
  // These are runtime secrets generated by this setup command, not source code.
  for (const name of ['PAY_SESSION_TOKEN_SECRET', 'PAY_RETRY_SECRET', 'CRON_SECRET']) {
    if (!process.env[name]) {
      const value = crypto.randomBytes(32).toString('base64');
      process.env[name] = value;
      contents += `\n${name}=${value}\n`;
    }
  }
  await fs.writeFile(envPath, contents, { mode: 0o600 });
  await ready();
  const tables = await query<{ tablename: string }>("SELECT tablename FROM pg_tables WHERE schemaname=current_schema() AND (tablename LIKE 'pay_%' OR tablename IN ('portal_deliveries','storeganise_deliveries')) ORDER BY tablename");
  console.log(JSON.stringify({ database: 'connected', credentials: 'verified from private server environment', tables: tables.rows.map(row => row.tablename) }, null, 2));
}
main().catch(error => { console.error('Setup failed:', error instanceof Error ? error.name : 'unknown'); process.exitCode = 1; }).finally(closeDatabase);
